import{_ as s,C as n,o as l,c,a2 as r,j as e,E as d,a as t}from"./chunks/framework.Dx-TCpNt.js";const _=JSON.parse('{"title":"リモート保存とバックアップ","description":"ローカルディスクが既定です。KomaYomi は raw/ から画像を読み、data/ に注釈を書き、生成ファイルを exports/ に書きます。その上で、サーバーは リモート画像ソース と リモートバックアップ先 を WebDAV またはマウント済み／SMB のネットワーク共有経由でサポートします…","frontmatter":{"description":"ローカルディスクが既定です。KomaYomi は raw/ から画像を読み、data/ に注釈を書き、生成ファイルを exports/ に書きます。その上で、サーバーは リモート画像ソース と リモートバックアップ先 を WebDAV またはマウント済み／SMB のネットワーク共有経由でサポートします…"},"headers":[],"relativePath":"ja/remote-backup.md","filePath":"ja/remote-backup.md","lastUpdated":1794768712000}'),i={name:"ja/remote-backup.md"};function g(p,o,m,u,h,b){const a=n("Badge");return l(),c("div",null,[o[6]||(o[6]=r('<h1 id="リモート保存とバックアップ" tabindex="-1">リモート保存とバックアップ <a class="header-anchor" href="#リモート保存とバックアップ" aria-label="Permalink to &quot;リモート保存とバックアップ&quot;">​</a></h1><h2 id="現在存在するもの" tabindex="-1">現在存在するもの <a class="header-anchor" href="#現在存在するもの" aria-label="Permalink to &quot;現在存在するもの&quot;">​</a></h2><p>ローカルディスクが既定です。KomaYomi は <code>raw/</code> から画像を読み、<code>data/</code> に注釈を書き、生成ファイルを <code>exports/</code> に書きます。その上で、サーバーは <strong>リモート画像ソース</strong> と <strong>リモートバックアップ先</strong> を WebDAV またはマウント済み／SMB のネットワーク共有経由でサポートします。<strong>データツール → ストレージ</strong> で設定し、<code>data/storage.json</code>（<code>schemaVersion: 1</code>）に保存されます。</p><p>さらに、持ち運べるローカルの安全網が2つ実装されています。</p><h3 id="リモート画像ソース-webdav-ネットワークドライブ" tabindex="-1">リモート画像ソース（WebDAV / ネットワークドライブ） <a class="header-anchor" href="#リモート画像ソース-webdav-ネットワークドライブ" aria-label="Permalink to &quot;リモート画像ソース（WebDAV / ネットワークドライブ）&quot;">​</a></h3><p>種類が <code>webdav</code> または <code>network</code> のストレージターゲットを <code>rawSource</code> として設定できます。</p><ul><li><strong>構造同期</strong> — <strong>同期</strong> はリモートツリーを走査し、そのフォルダ構成を <code>raw/</code> にゼロバイトのプレースホルダーファイルとしてミラーします（画像ファイルは最大 20,000 件）。既存のライブラリスキャナーと命名規則はそのまま機能し、プレースホルダーがどのページが存在するかを示します。</li><li><strong>オンデマンド取得</strong> — 画像のバイト列は、同期時ではなく、ページやサムネイルを初めて開いたときにダウンロードされます。取得したファイルは <code>data/cache/remote/files/</code> 以下に、プロバイダー id と相対パスの SHA-1 をアドレスとしてキャッシュされます。</li><li><strong>LRU キャッシュ</strong> — キャッシュは <code>cacheLimitMb</code>（既定 <strong>512 MB</strong>）で上限が決まります。書き込みのたびに、使用量が上限の <strong>90%</strong> を下回るまで、最も長く使われていないファイルから削除します。キャッシュはストレージ UI からクリアできます。</li><li><strong>オフライン時</strong> — キャッシュ済みのページは引き続き読めます。未キャッシュの画像は HTTP <strong>503</strong> とコード <code>ERR_REMOTE_UNAVAILABLE</code> を返し、サムネイルの取得失敗は <strong>502</strong> <code>ERR_THUMB_FETCH_FAILED</code> を返します。ライブラリはハングしたりページを黙って落としたりせず、ページを一覧し続けます。</li><li><strong>認証情報</strong> — ユーザー名は <code>storage.json</code> に保存され、パスワードは <strong>AES-256-GCM</strong> で <code>data/secrets.json.enc</code> に暗号化されます。インストールごとの鍵は <code>data/.secret.key</code>（モード <code>0600</code>）です。API は <code>hasSecret</code> のみを報告し、パスワードを返すことはありません。これは持ち運べるフォールバックであり、OS のキーチェーンではありません。データフォルダ全体を <code>.secret.key</code> と一緒にコピーした人は復号できます。</li><li><strong>WebDAV の詳細</strong> — Basic 認証、一覧と状態取得に <code>PROPFIND</code>、読み取りに <code>GET</code>、書き込みに <code>PUT</code>、リクエストタイムアウトは 10 秒です。読み取り専用のターゲットはソースとしては機能しますが、アップロードは拒否されます（<code>ERR_STORAGE_READONLY</code>）。</li></ul><h3 id="バックアップ-zip" tabindex="-1">バックアップ ZIP <a class="header-anchor" href="#バックアップ-zip" aria-label="Permalink to &quot;バックアップ ZIP&quot;">​</a></h3><ul><li>すべてのエントリに <code>data/</code> を前置し、<code>data/.backup-meta.json</code> マーカーを含む <code>data/</code> の ZIP を作成します。</li><li>サムネイルキャッシュと <code>.tmp</code> / <code>.log</code> ファイルを除外します。</li><li>ファイルは <code>exports/</code> に書き込まれ、ダウンロードとして提供されます。バックアップ先が選択されている場合、同じ ZIP がそのターゲットの <code>backups/backup-&lt;timestamp&gt;.zip</code> にアップロードされます。</li><li><strong>復元前に検査</strong> は、ファイル数、ページ数、ノート数、巻、テンプレート、プリセット、上書きされるファイル数、アーカイブのサイズを表示します。</li><li><strong>復元</strong> は <code>data/</code> 以下の同名ファイルを書き込みますが、バックアップにないページを削除はしません。何かを上書きする前に現在のデータのスナップショットが <code>exports/</code> に書き込まれるため、誤クリックも取り消せます。</li></ul><h3 id="mnproj-プロジェクトパッケージ" tabindex="-1"><code>.mnproj</code> プロジェクトパッケージ <a class="header-anchor" href="#mnproj-プロジェクトパッケージ" aria-label="Permalink to &quot;`.mnproj` プロジェクトパッケージ&quot;">​</a></h3><p><code>manifest.json</code>、ページ JSON、テンプレート、プリセットを含む ZIP で、2つのモードのいずれかです:</p><ul><li><strong>参照</strong> — 画像のパスと SHA-1 ハッシュを記録します。小さい。画像が移動した場合、インポートは選択したフォルダからまずハッシュで、次にファイル名で<strong>再リンク</strong>できます。</li><li><strong>パッケージ</strong> — 重複排除した画像を <code>assets/&lt;sha1&gt;.&lt;ext&gt;</code> に埋め込みます。自己完結で持ち運べますが、大きくなります。</li></ul><p>インポートの挙動:</p><ul><li>最初に <code>data/</code> のスナップショットが書き込まれます。</li><li>元のパッケージは <code>data/backups/projects/</code> に保持されます。</li><li>競合は<strong>上書き</strong>、<strong>マージ</strong>、<strong>スキップ</strong>で解決できます。</li><li><strong>マージ</strong> は、入力側のページにコマ／注釈がない場合に既存のものを保持し、ノートを id で統合し、既存のノートを決して削除しません。</li></ul><p>マニフェストのフィールドとフォルダ構成は <a href="/KomaYomi-docs/ja/data-format">データ形式</a> を参照してください。</p><h2 id="推奨される運用" tabindex="-1">推奨される運用 <a class="header-anchor" href="#推奨される運用" aria-label="Permalink to &quot;推奨される運用&quot;">​</a></h2><ol><li><strong><code>raw/</code> は大きなローカルディスク</strong>（または接続ドライブ）に置いてください。データの大部分を占め、gitignore の対象です。</li><li><strong><code>data/</code> はバックアップ ZIP で定期的にバックアップ</strong>してください。ほとんど JSON で小さく、作業のすべてが入っています。</li><li>同じ画像を既に持つマシン間で注釈を移すには、<strong><code>.mnproj</code> の参照モード</strong>を使ってください。</li><li>自己完結したプロジェクトを他の人に渡すには、<strong><code>.mnproj</code> のパッケージモード</strong>を使ってください。</li><li>生成した学習ドキュメントを残したい場合は <strong><code>exports/</code> のコピーを保管</strong>してください。gitignore の対象で、再生成できます。</li><li>大きなライブラリは NAS 上の<strong>リモートソース</strong>を使ってください。オンデマンドキャッシュがローカルへの完全なコピーを避けつつ、閲覧の応答性を保ちます。</li></ol><h2 id="単にフォルダを同期するだけではだめなのか" tabindex="-1">単にフォルダを同期するだけではだめなのか <a class="header-anchor" href="#単にフォルダを同期するだけではだめなのか" aria-label="Permalink to &quot;単にフォルダを同期するだけではだめなのか&quot;">​</a></h2><p><code>raw/</code>、<code>data/</code>、<code>exports/</code> をネットワークドライブや同期フォルダに置くことはできます。アプリはファイルをロックしませんが、書き込みはアトミック（<code>.tmp</code> + リネーム）なので、同期クライアントが書きかけの JSON を見る可能性は低いです。同じページを2台のマシンから同時に編集することは避けてください。最後の書き込みが勝ちます。</p><h2 id="予定-まだないもの" tabindex="-1">予定: まだないもの <a class="header-anchor" href="#予定-まだないもの" aria-label="Permalink to &quot;予定: まだないもの&quot;">​</a></h2><p>以下は<strong>実装されていません</strong>。期待値を明確にするために記載します:</p>',21)),e("ul",null,[e("li",null,[d(a,{type:"warning",text:"予定"}),o[0]||(o[0]=t()),o[1]||(o[1]=e("strong",null,"スケジュールバックアップ",-1)),o[2]||(o[2]=t(" — ローカルまたは設定したターゲットへの自動の定期的スナップショット。",-1))]),e("li",null,[d(a,{type:"warning",text:"予定"}),o[3]||(o[3]=t()),o[4]||(o[4]=e("strong",null,[e("code",null,"data/"),t(" のバージョン履歴付きリモート同期")],-1)),o[5]||(o[5]=t(" — WebDAV ターゲットは現在、画像を配信しバックアップ ZIP を受け取りますが、注釈データベース自体のバージョン管理は行いません。",-1))])]),o[7]||(o[7]=r('<p>それまでは、バックアップ ZIP、リモートバックアップのアップロード、<code>.mnproj</code> をサポート対象の転送手段として扱ってください。</p><h2 id="復元チェックリスト" tabindex="-1">復元チェックリスト <a class="header-anchor" href="#復元チェックリスト" aria-label="Permalink to &quot;復元チェックリスト&quot;">​</a></h2><ol><li><strong>バックアップ</strong> をクリックし、ZIP が <code>exports/</code>（または選択したリモートターゲット）に現れることを確認します。</li><li>復元するには <strong>検査</strong> を選び、件数を確認してから <strong>復元</strong> をクリックします。</li><li>復元後、ライブラリを再読み込みします。注釈のあるページはサイドバーにバッジが付きます。</li><li>プロジェクトのインポートで画像が見つからないと報告された場合は、<strong>再リンクディレクトリ</strong> をそれらの画像を含むフォルダに向け、<strong>マージ</strong>で再度インポートします。</li></ol>',3))])}const x=s(i,[["render",g]]);export{_ as __pageData,x as default};
